#include <stdio.h>
#include <stdlib.h>

#include "rbtree.h"

/* Manual sanity-check driver — not part of the graded `make
 * test`/`asan`/`memcheck` build. Exercises the basic API shape: create,
 * insert, find, foreach, validate, destroy. Won't show real tree
 * *behavior* until src/rbtree.c's core logic is implemented (rb_create
 * currently returns NULL) — for now it proves the demo's shape and the
 * API calls are wired correctly, and runs to completion either way. */

static const char *const SAMPLE_KEYS[] = {
    "banana", "apple", "cherry", "date", "fig",
};
#define SAMPLE_COUNT (sizeof(SAMPLE_KEYS) / sizeof(SAMPLE_KEYS[0]))

static rbtree_t *build_sample_tree(void) {
    rbtree_t *t = rb_create(free);
    if (t == NULL) {
        fprintf(stderr, "build_sample_tree: rb_create failed\n");
        return NULL;
    }

    for (size_t i = 0; i < SAMPLE_COUNT; i++) {
        int *rank = malloc(sizeof(*rank));
        if (rank == NULL) {
            fprintf(stderr, "build_sample_tree: out of memory\n");
            rb_destroy(t);
            return NULL;
        }
        *rank = (int)i;
        if (rb_insert(t, SAMPLE_KEYS[i], rank) != 0) {
            fprintf(stderr, "build_sample_tree: rb_insert(%s) failed\n", SAMPLE_KEYS[i]);
            free(rank); /* insert failed: caller (us) still owns rank */
            rb_destroy(t);
            return NULL;
        }
    }
    return t;
}

static void print_entry(const char *key, void *value, void *ctx) {
    (void)ctx;
    printf("  %s -> %d\n", key, *(int *)value);
}

static void print_all_entries_in_order(const rbtree_t *t) {
    if (t == NULL) {
        printf("print_all_entries_in_order: tree is NULL\n");
        return;
    }
    printf("entries (in order):\n");
    rb_foreach(t, print_entry, NULL);
}

static void confirm_lookup_works(const rbtree_t *t) {
    if (t == NULL) {
        printf("confirm_lookup_works: tree is NULL\n");
        return;
    }
    for (size_t i = 0; i < SAMPLE_COUNT; i++) {
        void *v = rb_find(t, SAMPLE_KEYS[i]);
        printf("  find(%s) -> %s\n", SAMPLE_KEYS[i], v != NULL ? "found" : "MISSING");
    }
    printf("  find(nonexistent) -> %s\n",
           rb_find(t, "nonexistent") == NULL ? "correctly absent" : "UNEXPECTEDLY FOUND");
}

static void confirm_tree_is_valid(const rbtree_t *t) {
    if (t == NULL) {
        printf("confirm_tree_is_valid: tree is NULL\n");
        return;
    }
    printf("rb_validate: %s (size=%zu)\n",
           rb_validate(t) == 0 ? "valid" : "INVALID", rb_size(t));
}

static void destroy_sample_tree(rbtree_t *t) {
    rb_destroy(t);
}

int main(void) {
    rbtree_t *t = build_sample_tree();
    print_all_entries_in_order(t);
    confirm_lookup_works(t);
    confirm_tree_is_valid(t);
    destroy_sample_tree(t);
    return 0;
}

#ifndef RBTREE_H
#define RBTREE_H
#include <stddef.h>

/* Red-black tree keyed by C strings (strcmp order); values are opaque
 * void *. See CLAUDE.md for the full ownership contract. */

typedef struct rbtree rbtree_t;
typedef void (*rb_value_free_fn)(void *value);

/* Returns NULL on allocation failure.
 * value_free may be NULL (values not owned). */
rbtree_t *rb_create(rb_value_free_fn value_free);

/* Copies key (tree owns the copy).
 * Takes ownership of value ONLY on success.
 * Overwriting an existing key frees the old value via value_free.
 * Returns 0 on success, -1 on allocation failure (tree unchanged, value NOT
 * consumed; caller still owns it). */
int rb_insert(rbtree_t *t, const char *key, void *value);

/* Returns the value, or NULL if absent. Tree retains ownership. */
void *rb_find(const rbtree_t *t, const char *key);

/* Removes key; frees the key copy and the value.
 * Returns 0, or -1 if absent. */
int rb_delete(rbtree_t *t, const char *key);

size_t rb_size(const rbtree_t *t);

/* In-order traversal. */
void rb_foreach(const rbtree_t *t,
                void (*fn)(const char *key, void *value, void *ctx),
                void *ctx);

/* Returns 0 iff all red-black invariants hold:
 * root is black; no red node has a red child; every root-to-NIL path
 * crosses the same number of black nodes; in-order traversal is strictly
 * increasing under strcmp; rb_size matches the actual node count. */
int rb_validate(const rbtree_t *t);

/* Frees all nodes, key copies, and (if owned) values. NULL-safe. */
void rb_destroy(rbtree_t *t);

#endif

